/* Reel v3 render strip for scene "s8" (generated by reel-v3/make_scenes.py; plan reel-v3-plan.md §5).
 * Each segment is one shot: scene time runs linearly over it while the camera eases from one window of
 * the 1440×1000 scene to another, fitted to the shot's box (GRAPHIC 1080×1920, SPLIT the top 1080×1000).
 */
import { renderAt as renderScene } from './scene.js';
import { setupHearing } from './hearing.js';
const STRIP = {"fps": 30, "segments": [{"shot": 25, "f0": 0, "frames": 105, "reel": [49.9, 50.9], "box": [0, 0, 1080, 1000], "cam": ["fit", "fit"], "extra": {"phase": 0}}, {"shot": 26, "f0": 105, "frames": 34, "reel": [51.0, 51.0], "box": [0, 0, 1080, 1920], "cam": [[560, 520, 1000], [560, 520, 900]], "extra": {"phase": 1}}, {"shot": 27, "f0": 139, "frames": 136, "reel": [51.0, 51.0], "box": [0, 0, 1080, 1920], "cam": [[560, 520, 1000], [560, 520, 880]], "extra": {"phase": 2}}, {"shot": 28, "f0": 275, "frames": 69, "reel": [50.3, 50.8], "box": [0, 0, 1080, 1000], "cam": ["fit", [900, 520, 1200]], "extra": {"phase": 0}}, {"shot": 29, "f0": 344, "frames": 82, "reel": [51.0, 51.0], "box": [0, 0, 1080, 1920], "cam": [[560, 520, 1000], [560, 520, 880]], "extra": {"phase": 3}}], "frames": 426};
const gsap = window.gsap;
const EZ = gsap.parseEase('power2.inOut');
const lerp = (a, b, u) => a + (b - a) * u;
const cam = document.getElementById('reelcam');
renderScene(51.0);
const paintHearing = setupHearing(); // the extended states, on each shot's own clock
const win = (c, box) => (c === 'fit' ? [720, 500, 1440] : c);
function renderFrame(f) {
  const seg = STRIP.segments.find((s) => f >= s.f0 && f < s.f0 + s.frames) ?? STRIP.segments.at(-1);
  const u = Math.min(1, Math.max(0, (f - seg.f0) / Math.max(1, seg.frames - 1)));
  renderScene(lerp(seg.reel[0], seg.reel[1], u));
  if (seg.extra?.phase != null) paintHearing(seg.extra.phase, (f - seg.f0) / 30);
  const [bx, by, bw, bh] = seg.box;
  const [c0, c1] = seg.cam ?? ['fit', 'fit'];
  const a = win(c0), b = win(c1), e = EZ(u);
  const cx = lerp(a[0], b[0], e), cy = lerp(a[1], b[1], e), w = lerp(a[2], b[2], e), s = bw / w;
  cam.style.transform = `translate(${(bx + bw / 2 - cx * s).toFixed(2)}px, ${(by + bh / 2 - cy * s).toFixed(2)}px) scale(${s.toFixed(5)})`;
}
const clock = { f: 0 };
const N = STRIP.frames;
const tl = gsap.timeline({ paused: true });
tl.to(clock, { f: N, duration: N / 30, ease: 'none', onUpdate: () => renderFrame(Math.min(N - 1, Math.floor(clock.f + 1e-6))) }, 0);
renderFrame(0);
export const timeline = tl;
